{
  "passageId": "joseon-slavery-civil-rights",
  "items": [
    {
      "id": "R1",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 노비가 매매되는 물적 존재이면서도 일부 권리를 인정받았다는 양면성을 제시한다."
    },
    {
      "id": "R2",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "조선 전기에서 왜란·호란 이후로 시대가 넘어가며 노비 수의 추세가 전환된다."
    },
    {
      "id": "R3",
      "type": "CAUSE",
      "otherName": "",
      "reason": "노비 수와 신분 격차의 변화가 실제로 노비에 대한 인식 변화를 일으켰다고 설명한다."
    },
    {
      "id": "R4",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "노비에 대한 인식 변화가 양반들의 새로운 노비 관련 글이 등장한 사상적 계기로 제시된다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "노비에 관한 글이 등장했다는 설명을 그 글에 담긴 구체적인 시각과 한계로 풀어 준다."
    },
    {
      "id": "R6",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "노비를 연약한 존재로 바라보는 시선이 주인의 온정적 태도를 넘어서지는 못했다는 한계를 밝힌다."
    },
    {
      "id": "R7",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "같은 양반들이 노비의 의지는 강조하면서도 불평등한 처지는 거론하지 않았다는 한계를 제시한다."
    },
    {
      "id": "R8",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "노비에게 미안함을 느꼈지만 신분 질서를 비판하는 데까지 나아가지는 않았다고 설명한다."
    },
    {
      "id": "R9",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "노비 문제를 바라보는 기존 양반들과 이익의 서로 다른 관점을 나란히 제시한다."
    },
    {
      "id": "R10",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "운명의 세 가지 분류를 인간의 관여 여부와 능동적 변화 가능성이라는 세부 내용으로 풀어 준다."
    },
    {
      "id": "R11",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "서로 다른 인물의 견해가 아니라 천명·성명과 조명의 인간사 관여 및 변화 가능성을 대비한다."
    },
    {
      "id": "R12",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "조명의 적용 대상을 왕과 고관대작으로 제한한 이전 학자들과 모든 사람으로 확대한 이익의 견해가 다르다."
    },
    {
      "id": "R13",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "모두를 조명의 대상으로 삼았다는 내용을 모든 구성원이 노력으로 운명을 바꿀 수 있다는 뜻으로 다시 말한다."
    },
    {
      "id": "R14",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "운명 변화와 비세습적 신분 결정이라는 이익의 구상을 노비 매매·세습 금지와 기회 개방이라는 구체적 방안으로 풀어 준다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "삶의 변화가 개인의 몫이라는 원칙이 국가의 역할을 최소한의 기반 보장으로 한정하는 견해를 뒷받침한다."
    },
    {
      "id": "R16",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "서구 기본권 사상의 유입이 민권 논의가 구체화된 사상적 배경으로 제시된다."
    },
    {
      "id": "R17",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "같은 유길준의 견해 안에서 두 권리를 절대성·상대성과 권리의 기원에 따라 대비한다."
    },
    {
      "id": "R18",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "근대 법률의 제정과 시행은 민의 천부 인권을 실질적으로 보장하기 위한 수단으로 제시된다."
    },
    {
      "id": "R19",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "근대 법률의 제정과 시행은 민의 인위적 권리를 실질적으로 보장하기 위한 수단으로 제시된다."
    },
    {
      "id": "R20",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "민이 무지하다는 인식이 교육받지 않은 민은 사회 혼란을 일으킬 수 있다는 판단의 근거가 된다."
    },
    {
      "id": "R21",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "유길준이 민의 권리 보장을 주장하면서도 민을 무지하고 혼란을 초래할 수 있는 존재로 보았다는 양면성을 제시한다."
    },
    {
      "id": "R22",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "유길준과 박영효는 모두 민의 권리를 보장하는 데 법이 필수적이라는 견해를 공유한다."
    },
    {
      "id": "R23",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "타고난 능력에 따라 귀천이 생긴다는 주장이 그에 따른 부림을 정당화하는 근거로 쓰인다."
    },
    {
      "id": "R24",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 온건 개화파가 노비 세습 금지를 지지하면서도 귀천과 부림을 정당화하는 양면성을 보인다."
    },
    {
      "id": "R25",
      "type": "CAUSE",
      "otherName": "",
      "reason": "개화파의 민권 주장이 여러 상황과 결합하여 실제 신분제 폐지 조치로 이어졌다고 설명한다."
    },
    {
      "id": "R26",
      "type": "CAUSE",
      "otherName": "",
      "reason": "온건 개화파를 포함한 개화파의 민권 주장이 여러 상황과 맞물려 법제상 신분제 폐지에 기여했다고 설명한다."
    },
    {
      "id": "R27",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "법으로 신분제를 폐지했는데도 현실에서는 노비가 남아 있었다는 법과 현실의 괴리를 제시한다."
    },
    {
      "id": "R28",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "법제상 신분제 폐지에도 사회적 차별은 지속되었다는 조치의 한계를 제시한다."
    },
    {
      "id": "R29",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "신분제 폐지 후에도 노비와 차별이 남은 상황이 독립 협회의 비판이 나온 사회적 배경으로 제시된다."
    },
    {
      "id": "R30",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자유와 평등이 하늘이 준 권리라는 원칙이 노비 소유와 매매를 비판하는 근거가 된다."
    },
    {
      "id": "R31",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "신분제 폐지 이후의 차별 문제를 일제 강점기라는 다음 시대로 이어 간다."
    },
    {
      "id": "R32",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "일제 강점기에도 계속된 신분 차별이 백정의 인권을 요구하는 형평 운동의 발생 배경으로 제시된다."
    },
    {
      "id": "R33",
      "type": "PROCESS",
      "otherName": "",
      "reason": "형평사 조직을 통한 운동의 시작에서 참여 세력의 결합에 따른 본격화로 이어지는 단계를 제시한다."
    },
    {
      "id": "R34",
      "type": "PROCESS",
      "otherName": "",
      "reason": "운동의 본격화 다음에 대중의 호응과 전국화가 이어졌다는 진행 순서를 제시한다."
    },
    {
      "id": "R35",
      "type": "CLASSIFICATION",
      "otherName": "",
      "reason": "형평 운동을 이루는 두 성격으로 인권 운동과 공동체 운동을 함께 제시한다."
    },
    {
      "id": "R36",
      "type": "BACKGROUND",
      "otherName": "",
      "reason": "운동의 도화선이었던 교육 차별이 형평 운동에서 교육 활동을 펼치게 된 배경으로 제시된다."
    },
    {
      "id": "R37",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "사회적 대우를 받으려면 소양이 필요하다는 인식이 교육 활동의 필요성을 뒷받침하는 근거가 된다."
    },
    {
      "id": "R38",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "존엄과 평등을 위한 활동이 일상적 실천에서 제도화의 추구로 확장된다."
    },
    {
      "id": "R39",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "형평 운동의 형성과 실천에 관한 논의에서 이후의 위축·변질과 역사적 영향에 관한 논의로 넘어간다."
    },
    {
      "id": "R40",
      "type": "CAUSE",
      "otherName": "",
      "reason": "형평사의 대동사 개칭이 운동 본래 성격의 상실로 이어지는 변화로 제시된다."
    },
    {
      "id": "R41",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "형평 운동이 본래 성격을 잃었지만 후대 인권 운동에는 상당한 영향을 남겼다고 평가한다."
    }
  ]
}

